  "id": "shipment_source_status",
  "description": "For an elevator dispatch: established loadout bin/site, hopper-named contributing tickets, candidate tickets already in that bin, and whether ticket-to-truck allocation remains unresolved. Does not infer a quantity split.",
  "parameters": {
    "dispatch": {"type": "string", "required": true}
  },
  "result": {
    "source_location": "{established, bin, bin_label, site, loadout_id, loaded_at, quantity_kg}",
    "established_contributing_identities": "hopper-named tickets (empty if none named)",
    "candidate_identities_in_source_bin": "tickets moved into the loadout bin before loaded_at",
    "source_allocation_unresolved": "boolean",
    "unresolved": "matching purpose_requirement_failure rows"
  },
  "invoke": "application/run shipment_source_status --dispatch PGE-OUT-5001"
}

{
  "id": "processor_receipt_provenance",
  "description": "Join mill_receipt to inbound_same_movement, outbound_same_movement / established_shipment, mill_process, and upstream shipment_source_status. Processing is present only when mill_process names the slip.",
  "parameters": {
    "processor_receipt": {"type": "string", "required": true}
  },
  "result": {
    "established_path": "{dispatch_ref, manifest_no, mill_receipt, outbound_link_basis, inbound_link_basis} or null",
    "processing": "mill run and output_batch or null",
    "upstream_source": "source bin and ticket allocation status of the linked dispatch",
    "unresolved_links": "{mill_receipt_missing, processing_run_missing, upstream_ticket_allocation}"
  },
  "invoke": "application/run processor_receipt_provenance --processor_receipt HFM-IN-601"
}

{
  "id": "custody_owner_at",
  "description": "Select the covering ownership_event for material at timestamp using [effective_start, effective_end) with empty end as open. Owner is owner_after; custodian is holder_after. Always surfaces the unrecorded_ownership completeness caveat.",
  "parameters": {
    "material": {"type": "string", "required": true},
    "timestamp": {"type": "string", "required": true, "format": "ISO-8601"}
  },
  "result": {
    "recorded_owner": "string or null",
    "recorded_custodian": "string or null",
    "covering_event": "ownership_event fields or null",
    "owner_recorded": "boolean",
    "custodian_recorded": "boolean"
  },
  "invoke": "application/run custody_owner_at --material DR-44 --timestamp 2025-09-03T12:00:00-05:00"
}

{
  "id": "inspection_downstream_scope",
  "description": "From a lab sample, resolve local_lot aliases. If material_hint names a mill receipt, downstream is that slip and any mill_process output. Otherwise follow ticket_into_bin into later loadouts: hopper-named exclusive allocation is established; unnamed bin occupants stay unresolved.",
  "parameters": {
    "sample": {"type": "string", "required": true}
  },
  "result": {
    "sampled_identities": "string[]",
    "established_affected": "{shipments, processor_receipts, processed_outputs}",
    "possible_unallocated": "same shape for links that remain unresolved",
    "unresolved_scope": "array"
  },
  "invoke": "application/run inspection_downstream_scope --sample SMP-7714A"
}

